sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform shader blurred;
uniform float blur;
uniform float mode;
half4 main(float2 coord) {
    half4 src = image.eval(coord);
    if (blur <= 0.0) return src;
    if (mode > 0.5) {
        half4 b = blurred.eval(coord);
        if (b.a <= 0.0) return half4(0.0);
        half3 rgb = src.a > 0.0 ? src.rgb / src.a : b.rgb / b.a;
        return half4(rgb * b.a, b.a);
    }
    if (src.a <= 0.0) return src;
    float soft = clamp((float(blurred.eval(coord).a) - 0.5) * 2.0, 0.0, 1.0);
    return src * half(soft);
}
